def one_span(a, b):
    wa, wb = a.split(), b.split()
    ops = [o for o in difflib.SequenceMatcher(None, wa, wb, autojunk=False).get_opcodes() if o[0] != "equal"]
    return len(ops) == 1


def main():
    cl = json.load(open(os.path.join(ORIG, "cloze.json")))
    al = json.load(open(os.path.join(ORIG, "alter.json")))
    gr = json.load(open(os.path.join(ORIG, "grids.json")))
    n = len(cl)
    for i, (t, art, text, acc, why) in enumerate(C, 1):
        assert text.count("[[") == 1 and text.count("]]") == 1, text
        cl.append({"id": f"CZ-PR{i}", "topic": t, "art": art, "text": text, "accept": acc, "why": why})
    for i, (t, art, o, a, why) in enumerate(A, 1):
        assert one_span(o, a), (art, o, a)
        al.append({"id": f"AL-PR{i}", "topic": t, "art": art, "original": o, "altered": a, "why": why})
    gr += GRIDS
    for name, data in (("cloze.json", cl), ("alter.json", al), ("grids.json", gr)):
        json.dump(data, open(os.path.join(OUT, name), "w"), ensure_ascii=False, indent=1)
    print(f"cloze +{len(C)} = {len(cl)}; alter +{len(A)} = {len(al)}; grids +{len(GRIDS)} = {len(gr)}")


if __name__ == "__main__":
    main()
